import{_ as t,o as a,c as r,a5 as i}from"./chunks/framework.BrSBneze.js";const u=JSON.parse('{"title":"Report results","description":"","frontmatter":{},"headers":[],"relativePath":"benchmark/results.md","filePath":"benchmark/results.md","lastUpdated":1788882780000}'),n={name:"benchmark/results.md"};function o(s,e,d,l,p,c){return a(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="report-results" tabindex="-1">Report results <a class="header-anchor" href="#report-results" aria-label="Permalink to &quot;Report results&quot;">​</a></h1><p>Report performance per attachment and preserve the trial-level data. Aggregate values alone hide the failure modes and stage progression that make the benchmark informative.</p><h2 id="recommended-metrics" tabindex="-1">Recommended metrics <a class="header-anchor" href="#recommended-metrics" aria-label="Permalink to &quot;Recommended metrics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Calculation</th><th>Report for</th></tr></thead><tbody><tr><td>Success rate</td><td>Successful trials ÷ recorded trials</td><td>Every attachment</td></tr><tr><td>Completion time</td><td>Median and individual successful-trial times</td><td>Every attachment with successes</td></tr><tr><td>Attempts</td><td>Median and individual counts</td><td>Every attachment</td></tr><tr><td>Regrasps</td><td>Median and individual counts</td><td>Every attachment</td></tr><tr><td>Stage completion</td><td>Fraction reaching each stage</td><td>Composed tasks</td></tr><tr><td>Failure distribution</td><td>Count by primary failure cause</td><td>Unsuccessful trials</td></tr><tr><td>Strategy distribution</td><td>Count of prehensile and non-prehensile trials</td><td>Every attachment</td></tr></tbody></table><p>With five trials per attachment, always show the numerator and denominator—for example, <code>4/5 (80%)</code>—rather than only a percentage.</p><h2 id="keep-conditions-separate" tabindex="-1">Keep conditions separate <a class="header-anchor" href="#keep-conditions-separate" aria-label="Permalink to &quot;Keep conditions separate&quot;">​</a></h2><p>Do not merge results across:</p><ul><li>different end-effectors;</li><li>different control interfaces or policies;</li><li>horizontal and vertical board mounting;</li><li>ball valve trials with and without the friction ring;</li><li>materially different print settings or modified parts; or</li><li>simulation and physical trials.</li></ul><h2 id="accompanying-files" tabindex="-1">Accompanying files <a class="header-anchor" href="#accompanying-files" aria-label="Permalink to &quot;Accompanying files&quot;">​</a></h2><p>A complete submission contains 65 trials: five for each of the 13 conditions. Include these files:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>result-package/</span></span>
<span class="line"><span>├── trials.csv</span></span>
<span class="line"><span>├── setup.jpg</span></span>
<span class="line"><span>├── platform.md</span></span>
<span class="line"><span>├── manifest.json</span></span>
<span class="line"><span>├── session.json</span></span>
<span class="line"><span>├── recording-instructions.md</span></span>
<span class="line"><span>└── videos/              # one recording per trial</span></span></code></pre></div><p>The platform description identifies the robot, end-effector, control method, board orientation, calibration notes, HiveBoard version, printing parameters, post-processing, and any protocol deviations.</p><p>The <a href="/hiveboard-docs/benchmark/evaluation-runner">Evaluation Runner</a> generates the ZIP after all 65 trial entries and required setup details pass validation. Attach a JPEG setup photograph to include it as <code>setup.jpg</code>, or add it after extracting the ZIP. Add the recordings to <code>videos/</code> using the filenames in <code>recording-instructions.md</code>.</p><p>“Trial records complete” refers to the log and setup fields. It does not confirm that all supporting files are present or that an organizer has reviewed the outcomes. The manifest lists the expected recordings and whether the setup photograph was included when the ZIP was generated.</p><h2 id="submit-for-organizer-review" tabindex="-1">Submit for organizer review <a class="header-anchor" href="#submit-for-organizer-review" aria-label="Permalink to &quot;Submit for organizer review&quot;">​</a></h2><p>Submissions are reviewed by email. There is no upload server or automatic approval.</p><ol><li>Complete all 65 trial entries and the required platform details in the <a href="/hiveboard-docs/benchmark/evaluation-runner">Evaluation Runner</a>.</li><li>Download and extract the results ZIP. Add <code>setup.jpg</code> and the 65 external-camera recordings using the filenames in <code>recording-instructions.md</code>. For simulated evaluations, provide screen recordings of the complete trials.</li><li>Recompress the completed folder and upload it to storage you control. Give <strong><a href="mailto:ricardo.godoy@usp.br" target="_blank" rel="noreferrer">ricardo.godoy@usp.br</a></strong> download access and keep the package private during review. Keep the link available until review is complete.</li><li>In the runner&#39;s Review step, select <strong>Submit for review</strong>. Enter your contact name, email, institution (or Independent), and the package link. Robot, end-effector, and control interface are taken from the evaluation setup.</li><li>Confirm file completeness and permission to publish the approved trial data, platform description, setup photograph, and recordings. You must have permission to share the materials, including permission from identifiable people in the media.</li><li>Select <strong>Prepare submission email</strong>, review the draft, and send it from your email application. If no email application opens, copy the draft and send it to <strong><a href="mailto:ricardo.godoy@usp.br" target="_blank" rel="noreferrer">ricardo.godoy@usp.br</a></strong>. Opening a draft does not send it or confirm receipt.</li></ol><p>Contact details and the private package link are included only in the email draft, not in the exported results or session backups. They must be entered again after reloading the page. Results can still be downloaded without submitting or granting publication permission.</p><h3 id="organizer-review" tabindex="-1">Organizer review <a class="header-anchor" href="#organizer-review" aria-label="Permalink to &quot;Organizer review&quot;">​</a></h3><p>The organizer checks the 13 conditions and five records per condition, platform metadata, photograph, recording filenames, and the recorded outcomes against the video evidence. Browser validation is a preliminary check; it does not replace this review.</p><p>Corrections are requested by email. Keep the same submission ID when supplying a corrected package and describe the changes. Publication follows approval and requires the submitter&#39;s recorded permission.</p><p>Before publishing, prepare a separate copy containing only the approved trial data, platform description, photograph, and recordings. Check free-text notes and media for personal information. Do not publish contact details, private download links, correspondence, or the organizer&#39;s review notes. Public result pages and rankings will be added separately.</p><h2 id="interpretation" tabindex="-1">Interpretation <a class="header-anchor" href="#interpretation" aria-label="Permalink to &quot;Interpretation&quot;">​</a></h2><p>HiveBoard exposes different constraints across attachments. A low score can indicate incompatible grasp geometry, insufficient force, kinematic limits, perception difficulty, slip, or insufficient control precision. Report these causes instead of interpreting every unsuccessful trial as the same type of failure.</p><p>Comparisons between platforms should state which factors differ. The protocol characterizes the complete manipulation platform and should not be used to attribute a result to the gripper, robot, controller, or operator in isolation without a controlled experiment.</p>`,25)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
